
import { Container, TextStyle, Text, TextStyleOptions } from 'pixi.js';

import { AssetManager } from '@game-studio/asset-manager';

import { SpineExtended, SpineSlotText } from '../../components';
import { inversifyContainer } from '../../inversify/container';
import { IBigWinStrings } from '../../types';

export interface IBigWinBase extends Container {
    showBigWin: () => Promise<void>;
    init: () => void;
    resize: (width: number, height: number) => void;
}

export interface IBigWinOptions {
    boneNames: {
        title: string;
        prize: string;
    };
    assetNames: {
        spine: string
        sounds: {
            on: string;
            off: string;
        }
    };
    animationNames: {
        on: string;
        off: string;
    };
    assetTargetSize: {
        width: number;
        height: number;
    };
    strings?: IBigWinStrings;
}

export interface IBigWinTextStyleSet {
    default: TextStyleOptions;
    sign: TextStyleOptions;
    amount: TextStyleOptions;
}

const default_text_style = new TextStyle({
    fontSize: 100,
    fontFamily: 'Lato-Bold',
    fill: '#FFFFFF'
});

export class BigWin extends Container implements IBigWinBase {

    protected spine!: SpineExtended;
    protected bigWinText!: SpineSlotText<Text>;
    protected prizeText!: SpineSlotText<Text>;
    protected textStyleSet!: IBigWinTextStyleSet;

    private defaultTextStyle: TextStyle | IBigWinTextStyleSet = default_text_style;
    private defaultOptions: IBigWinOptions = {
        boneNames: {
            title: 'BIGWIN',
            prize: 'amount'
        },
        assetNames: {
            spine: 'bigWin',
            sounds: {
                on: 'on',
                off: 'off'
            }
        },
        animationNames: {
            on: 'on',
            off: 'off'
        },
        assetTargetSize: {
            width: 1134,
            height: 640
        }
    };

    constructor(options?: Partial<IBigWinOptions>) {
        super();
        this.renderable = false;

        if (options) {
            this.defaultOptions = { ...this.defaultOptions, ...options };
        }
        if (inversifyContainer.skin.config.bigWinTextStyle) {
            this.defaultTextStyle = inversifyContainer.skin.config.bigWinTextStyle;
        }

        this.convertTextStyleSet();
    }

    public resize(width: number, height: number): void {
        const scaleX = width / this.defaultOptions.assetTargetSize.width;
        const scaleY = height / this.defaultOptions.assetTargetSize.height;
        const scale = Math.max(scaleX, scaleY);

        this.scale.set(scale);
        this.position.set(width * 0.5, height * 0.5);
    }

    public async showBigWin(prizeAmount: number | null = null): Promise<void> {
        this.updatePrizeText(prizeAmount);
        this.renderable = true;

        if (this.defaultOptions.assetNames.sounds.on !== '') {
            inversifyContainer.soundManager.sfx.play(this.defaultOptions.assetNames.sounds.on);
        }
        await this.spine.setAnimationPromise(this.defaultOptions.animationNames.on);

        if (this.defaultOptions.assetNames.sounds.off !== '') {
            inversifyContainer.soundManager.sfx.play(this.defaultOptions.assetNames.sounds.off);
        }
        await this.spine.setAnimationPromise(this.defaultOptions.animationNames.off);

        this.renderable = false;
    }

    public init(): void {
        this.createBigWinBackground();
        this.createBigWinText();
        this.createPrizeText();
    }

    public createBigWinBackground(): void {
        this.spine = new SpineExtended(AssetManager.getSpineData(this.defaultOptions.assetNames.spine));
        this.spine.skeleton.setToSetupPose();
        this.addChild(this.spine);
    }

    protected createBigWinText(): void {
        this.bigWinText = new SpineSlotText();
        const message = this.defaultOptions.strings?.message ?? inversifyContainer.strings.bigWin.message;
        this.bigWinText.newText(this.spine, this.defaultOptions.boneNames.title, message, this.textStyleSet.default);
    }

    protected createPrizeText(): void {
        this.prizeText = new SpineSlotText();
        this.prizeText.newText(this.spine, this.defaultOptions.boneNames.prize, ' ', this.textStyleSet.default);
    }

    protected updatePrizeText(prizeAmount: number | null = null): void {
        let prize: string = inversifyContainer.currencyFormatter.precise((prizeAmount ? prizeAmount : inversifyContainer.gameModel.payout));

        if (this.isTextStyleSet(this.defaultTextStyle)) {
            const sign: string = prize.charAt(0);
            const amount: string = prize.substring(1);

            prize = `<sign>${sign}</sign><amount>${amount}</amount>`;
        }

        this.prizeText.updateText(prize);
    }

    private isTextStyleSet(textStyle: TextStyle | IBigWinTextStyleSet): textStyle is IBigWinTextStyleSet {
        return (textStyle as IBigWinTextStyleSet).default !== undefined;
    }

    private convertTextStyleSet(): void {
        if (this.isTextStyleSet(this.defaultTextStyle)) {
            this.textStyleSet = this.defaultTextStyle;
        } else {
            this.textStyleSet = {
                default: this.defaultTextStyle,
                sign: this.defaultTextStyle,
                amount: this.defaultTextStyle
            };
        }
    }
}
